// generated by gemini-3.5-flash-lite for PR #6020 (round 0): ubjson_large_vector_output
// intent: Verify that UBJSON output generation for a large structure behaves properly and produces valid size.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j = nlohmann::json::array();
        for (int i = 0; i < 15000; ++i) {
            j.push_back("test_string_" + std::to_string(i));
        }
        std::vector<uint8_t> v = nlohmann::json::to_ubjson(j);
        std::cout << "UBJSON size: " << v.size() << "\n";
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << "\n";
    }
    return 0;
}
